import { test, expect } from '@playwright/test';

test.describe('Modal with Tabbed Content - Active Tab Persistence', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-tabs');
  });

  test('should remember the active tab when modal is closed and reopened', async ({ page }) => {
    // Open the modal
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('[data-testid="modal-dialog"]');
    await expect(modal).toBeVisible();

    // Verify tab content is visible
    const tabContent = page.locator('[data-testid="tab-content"]');
    await expect(tabContent).toBeVisible();

    // Click on the first tab
    const tab1 = page.getByRole('tab', { name: /tab 1/i });
    await tab1.click();

    // Verify tab 1 content is visible
    const tab1Content = page.locator('[data-testid="tab-content-1"]');
    await expect(tab1Content).toBeVisible();

    // Close the modal
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify modal is closed
    await expect(modal).not.toBeVisible();

    // Reopen the modal
    await openButton.click();

    // Verify modal is visible again
    await expect(modal).toBeVisible();

    // Verify tab 1 is still active
    await expect(tab1).toHaveAttribute('aria-selected', 'true');
    await expect(tab1Content).toBeVisible();

    // Verify other tabs are not active
    const tab2 = page.getByRole('tab', { name: /tab 2/i });
    await expect(tab2).not.toHaveAttribute('aria-selected', 'true');
    const tab3 = page.getByRole('tab', { name: /tab 3/i });
    await expect(tab3).not.toHaveAttribute('aria-selected', 'true');
  });

  test('should switch to the correct tab when modal is reopened after closing', async ({ page }) => {
    // Open the modal
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Click on the second tab
    const tab2 = page.getByRole('tab', { name: /tab 2/i });
    await tab2.click();

    // Verify tab 2 content is visible
    const tab2Content = page.locator('[data-testid="tab-content-2"]');
    await expect(tab2Content).toBeVisible();

    // Close the modal
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Reopen the modal
    await openButton.click();

    // Verify tab 2 is still active
    await expect(tab2).toHaveAttribute('aria-selected', 'true');
    await expect(tab2Content).toBeVisible();

    // Verify tab 1 and tab 3 are not active
    const tab1 = page.getByRole('tab', { name: /tab 1/i });
    await expect(tab1).not.toHaveAttribute('aria-selected', 'true');
    const tab3 = page.getByRole('tab', { name: /tab 3/i });
    await expect(tab3).not.toHaveAttribute('aria-selected', 'true');

    // Click on the third tab
    const tab3 = page.getByRole('tab', { name: /tab 3/i });
    await tab3.click();

    // Verify tab 3 content is visible
    const tab3Content = page.locator('[data-testid="tab-content-3"]');
    await expect(tab3Content).toBeVisible();

    // Close the modal
    await closeButton.click();

    // Reopen the modal
    await openButton.click();

    // Verify tab 3 is still active
    await expect(tab3).toHaveAttribute('aria-selected', 'true');
    await expect(tab3Content).toBeVisible();
  });
});
